class Solution:
    def multiply(self, poly1: List[int], poly2: List[int]) -> List[int]:
        n, m = len(poly1), len(poly2)
        res = [0] * (n + m - 1)
        for i, a in enumerate(poly1):
            if a:
                for j, b in enumerate(poly2):
                    res[i + j] += a * b
        return res

