class Solution:
    def multiply(self, poly1: List[int], poly2: List[int]) -> List[int]:
        SH = 64
        MASK = (1 << SH) - 1
        a = b = 0
        for i, c in enumerate(poly1):
            a |= (c & MASK) << (SH * i)
        for i, c in enumerate(poly2):
            b |= (c & MASK) << (SH * i)
        p = a * b
        rs = len(poly1) + len(poly2) - 1
        out = []
        for i in range(rs):
            blk = (p >> (SH * i)) & MASK
            if blk >= (1 << 63):
                blk -= (1 << SH)
            out.append(blk)
        return out

