class Solution {
    long long pw(long long b, long long e, long long m) {
        long long r = 1; b %= m;
        while (e > 0) { if (e & 1) r = r * b % m; b = b * b % m; e >>= 1; }
        return r;
    }
    void ntt(vector<long long>& a, long long mod, long long root, bool inv) {
        int n = a.size();
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            for (; j & bit; bit >>= 1) j ^= bit;
            j ^= bit;
            if (i < j) swap(a[i], a[j]);
        }
        for (int len = 2; len <= n; len <<= 1) {
            long long w = pw(root, (mod - 1) / len, mod);
            if (inv) w = pw(w, mod - 2, mod);
            for (int i = 0; i < n; i += len) {
                long long wn = 1;
                for (int j = 0; j < len / 2; j++) {
                    long long u = a[i + j], v = a[i + j + len / 2] * wn % mod;
                    a[i + j] = (u + v) % mod;
                    a[i + j + len / 2] = (u - v + mod) % mod;
                    wn = wn * w % mod;
                }
            }
        }
        if (inv) {
            long long ni = pw(n, mod - 2, mod);
            for (auto& x : a) x = x * ni % mod;
        }
    }
public:
    vector<int> multiply(vector<int>& poly1, vector<int>& poly2) {
        int rs = poly1.size() + poly2.size() - 1, sz = 1;
        while (sz < rs) sz <<= 1;
        long long mods[2] = {998244353LL, 754974721LL};
        long long roots[2] = {3, 11};
        vector<vector<long long>> res(2, vector<long long>(rs));
        for (int t = 0; t < 2; t++) {
            vector<long long> a(sz, 0), b(sz, 0);
            for (int i = 0; i < (int)poly1.size(); i++) a[i] = ((poly1[i] % mods[t]) + mods[t]) % mods[t];
            for (int i = 0; i < (int)poly2.size(); i++) b[i] = ((poly2[i] % mods[t]) + mods[t]) % mods[t];
            ntt(a, mods[t], roots[t], false);
            ntt(b, mods[t], roots[t], false);
            for (int i = 0; i < sz; i++) a[i] = a[i] * b[i] % mods[t];
            ntt(a, mods[t], roots[t], true);
            for (int i = 0; i < rs; i++) res[t][i] = a[i];
        }
        long long m1 = mods[0], m2 = mods[1];
        long long inv1 = pw(m1 % m2, m2 - 2, m2);
        vector<int> out(rs);
        for (int i = 0; i < rs; i++) {
            long long r1 = res[0][i], r2 = res[1][i];
            long long kk = ((r2 - r1 + m2) % m2) * inv1 % m2;
            long long val = r1 + kk * m1;
            if (val > m1 * m2 / 2) val -= m1 * m2;
            out[i] = (int)val;
        }
        return out;
    }
};

