class Solution {
    private long pw(long b, long e, long m) {
        long r = 1; b %= m;
        while (e > 0) { if ((e & 1) == 1) r = r * b % m; b = b * b % m; e >>= 1; }
        return r;
    }
    private void ntt(long[] a, long mod, long root, boolean inv) {
        int n = a.length;
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            for (; (j & bit) != 0; bit >>= 1) j ^= bit;
            j ^= bit;
            if (i < j) { long t = a[i]; a[i] = a[j]; a[j] = t; }
        }
        for (int len = 2; len <= n; len <<= 1) {
            long w = pw(root, (mod - 1) / len, mod);
            if (inv) w = pw(w, mod - 2, mod);
            for (int i = 0; i < n; i += len) {
                long wn = 1;
                for (int j = 0; j < len / 2; j++) {
                    long u = a[i + j], v = a[i + j + len / 2] * wn % mod;
                    a[i + j] = (u + v) % mod;
                    a[i + j + len / 2] = (u - v + mod) % mod;
                    wn = wn * w % mod;
                }
            }
        }
        if (inv) {
            long ni = pw(n, mod - 2, mod);
            for (int i = 0; i < n; i++) a[i] = a[i] * ni % mod;
        }
    }
    public int[] multiply(int[] poly1, int[] poly2) {
        int rs = poly1.length + poly2.length - 1, sz = 1;
        while (sz < rs) sz <<= 1;
        long[] mods = {998244353L, 754974721L};
        long[] roots = {3L, 11L};
        long[][] res = new long[2][rs];
        for (int t = 0; t < 2; t++) {
            long[] a = new long[sz], b = new long[sz];
            for (int i = 0; i < poly1.length; i++) a[i] = ((poly1[i] % mods[t]) + mods[t]) % mods[t];
            for (int i = 0; i < poly2.length; i++) b[i] = ((poly2[i] % mods[t]) + mods[t]) % mods[t];
            ntt(a, mods[t], roots[t], false);
            ntt(b, mods[t], roots[t], false);
            for (int i = 0; i < sz; i++) a[i] = a[i] * b[i] % mods[t];
            ntt(a, mods[t], roots[t], true);
            for (int i = 0; i < rs; i++) res[t][i] = a[i];
        }
        long m1 = mods[0], m2 = mods[1];
        long inv1 = pw(m1 % m2, m2 - 2, m2);
        int[] out = new int[rs];
        for (int i = 0; i < rs; i++) {
            long r1 = res[0][i], r2 = res[1][i];
            long kk = ((r2 - r1 + m2) % m2) * inv1 % m2;
            long val = r1 + kk * m1;
            if (val > m1 * m2 / 2) val -= m1 * m2;
            out[i] = (int) val;
        }
        return out;
    }
}

