var multiply = function(poly1, poly2) {
    const SH = 64n, MASK = (1n << SH) - 1n;
    let a = 0n, b = 0n;
    for (let i = 0; i < poly1.length; i++) a |= (BigInt(poly1[i]) & MASK) << (SH * BigInt(i));
    for (let i = 0; i < poly2.length; i++) b |= (BigInt(poly2[i]) & MASK) << (SH * BigInt(i));
    const p = a * b;
    const rs = poly1.length + poly2.length - 1;
    const out = [];
    for (let i = 0; i < rs; i++) {
        let blk = (p >> (SH * BigInt(i))) & MASK;
        if (blk >= (1n << 63n)) blk -= (1n << SH);
        out.push(Number(blk));
    }
    return out;
};
